namespace LastRail.Tests.EditMode {public sealed class BResultReportTransportTests {
 internal static BRouteRuntimeObservation Original(){var root=(JObject)JObject.Parse(File.ReadAllText("D:/Project/LASTRAIL/QA/CombatBMigration-20261004/BNativeTwoWave-20261005/two-wave-http-result.json"))["controller"];var r=(JObject)root["route"];var binding=BRouteBinding.Read(r.ToString(),(string)r["packetHash"],(string)r["accountId"],(string)r["runId"]);return (BRouteRuntimeObservation)Activator.CreateInstance(typeof(BRouteRuntimeObservation),BindingFlags.Instance|BindingFlags.NonPublic,null,new object[]{binding,(JObject)root["nodeSession"]},null);}
 internal static JObject Receipt(BResultReportRequest q){var b=q.Body();var n=b["nodeSession"]["runtime"];return new JObject{["version"]=BResultConsistencyReceipt.Version,["evidenceRef"]="B_RESULT:opaque/ref",["requestId"]=q.RequestId,["reportOriginMapRevision"]=b["reportOriginMapRevision"].DeepClone(),["originalEventId"]=n["commands"].Last["eventId"].DeepClone(),["commandRevision"]=((JArray)n["commands"]).Count,["nativeSequence"]=n["sequence"].DeepClone(),["checkpointHash"]=b["checkpointHash"].DeepClone(),["completedWaves"]=2,["verificationLevel"]="STRUCTURE_SOURCE_RESULT_CONSISTENCY",["combatTruth"]="NOT_PROVEN",["fullNativeReplayPerformed"]=false,["arrivalAccepted"]=false,["progressAuthorized"]=false,["missingSources"]=new JArray("ORIGINAL_DEPARTURE_FORMATION"),["rewardsAuthorized"]=false};}
 sealed class Mock:IGameApiAuthenticatedHttpTransport {public int Calls;public RunApiHttpRequest Last;public GameApiAccessToken Token;public Func<RunApiHttpRequest,Task<GameApiAuthenticatedHttpResult>> Reply;public Task<GameApiAuthenticatedHttpResult> SendAsync(RunApiHttpRequest r,GameApiAccessToken t){Calls++;Last=r;Token=t;return Reply(r);}}
 static GameApiAuthenticatedHttpResult Ok(JObject value)=>GameApiAuthenticatedHttpResult.Succeeded(RunApiHttpResponse.Success(200,value.ToString(Newtonsoft.Json.Formatting.None),new[]{new RunApiHttpHeader("Cache-Control","no-store")}));
 static GameApiAccessToken Token()=>new GameApiAccessToken("lst1.local-test-only");
 [Test] public void TypedReportTransportMustConnectToExistingController(){Assert.NotNull(typeof(BRouteSessionController).GetMethod("SubmitOriginalResultReportAsync"));Assert.NotNull(typeof(BRouteSessionController).GetMethod("RecoverOriginalResultReportAsync"));}
 [Test] public void RequestIsImmutablePersistableAndDoesNotInventMapOrEventCursor(){var o=Original();var q=new BResultReportRequest(o,"fixed-request");Assert.AreEqual(2,(long)q.Body()["reportOriginMapRevision"]);Assert.AreEqual(507,((JArray)q.Body()["nodeSession"]["runtime"]["commands"]).Count);Assert.IsTrue(JToken.DeepEquals(o.OriginalNodeSession,q.Body()["nodeSession"]));var saved=q.Capture();var restored=BResultReportRequest.Restore(saved,BDirectAttackInput.Digest(saved),o);Assert.AreEqual(q.BodyJson,restored.BodyJson);q.Body()["version"]="changed";Assert.AreEqual(BResultReportRequest.Version,(string)q.Body()["version"]);saved["body"]["reportOriginMapRevision"]=507;Assert.Throws<ArgumentException>(()=>BResultReportRequest.Restore(saved,BDirectAttackInput.Digest(saved),o));}
 [Test] public async Task AuthenticatedPostRetriesExactBodyThenRecoversOriginalImmutableReport(){var q=new BResultReportRequest(Original(),"lost-response-request");string first=null;var m=new Mock();m.Reply=r=>{first=first??r.BodyJson;Assert.AreEqual(first,r.BodyJson);return Task.FromResult(m.Calls==1?GameApiAuthenticatedHttpResult.NetworkError("lost"):Ok(Receipt(q)));};var client=new BResultReportHttpClient(m);var token=Token();var failure=Assert.ThrowsAsync<BResultReportHttpException>(async()=>await client.SubmitAsync(q,token));Assert.IsTrue(failure.CanRetrySameRequest);var receipt=await client.SubmitAsync(q,token);Assert.AreSame(token,m.Token);Assert.AreEqual("POST",m.Last.Method);Assert.AreEqual(q.RequestId,m.Last.Headers.Single(x=>x.Name=="Idempotency-Key").Value);Assert.AreEqual(BResultReportRequest.Version,m.Last.Headers.Single(x=>x.Name=="X-B-Result-Version").Value);Assert.IsFalse(receipt.ProgressAuthorized);m.Reply=r=>Task.FromResult(Ok(new JObject{["receipt"]=Receipt(q),["report"]=q.Body()}));var recovered=await client.RecoverAsync(q,receipt.EvidenceRef,token);Assert.IsTrue(JToken.DeepEquals(receipt.Capture(),recovered.Capture()));Assert.AreEqual("GET",m.Last.Method);Assert.IsNull(m.Last.BodyJson);Assert.That(m.Last.EndpointPath,Does.EndWith("B_RESULT%3Aopaque%2Fref"));Assert.IsFalse(m.Last.Headers.Any(x=>x.Name=="If-Match"||x.Name=="Idempotency-Key"));}
 [TestCase(400)][TestCase(401)][TestCase(404)][TestCase(409)][TestCase(413)] public void OriginalHttpErrorsPreserveStatusAndExactCode(int status){var q=new BResultReportRequest(Original(),"errors");var response=RunApiHttpResponse.Success(status,"{\"accepted\":false,\"errorCode\":\"original_code\"}");var m=new Mock{Reply=r=>Task.FromResult(status==401?GameApiAuthenticatedHttpResult.AuthRequired(response,"original_code",null):GameApiAuthenticatedHttpResult.Succeeded(response))};var error=Assert.ThrowsAsync<BResultReportHttpException>(async()=>await new BResultReportHttpClient(m).SubmitAsync(q,Token()));Assert.AreEqual(status,error.StatusCode);Assert.AreEqual("original_code",error.ErrorCode);Assert.AreEqual(status==409,error.RequiresMapRefresh);Assert.AreEqual(status==401,error.RequiresAuthentication);Assert.IsFalse(error.CanRetrySameRequest);}
 [TestCase("commandRevisionString")][TestCase("completedWavesString")][TestCase("checkpointHash")][TestCase("commandRevision")][TestCase("arrivalAccepted")][TestCase("rewardsAuthorized")] public void ReceiptCannotAuthorizeDifferentOriginalOrUnprovidedPermissions(string field){var q=new BResultReportRequest(Original(),"receipt-fault");var p=Receipt(q);if(field=="commandRevisionString")p["commandRevision"]="507";else if(field=="completedWavesString")p["completedWaves"]="2";else if(field=="checkpointHash")p[field]="wrong";else if(field=="commandRevision")p[field]=2;else p[field]=true;Assert.Throws<ArgumentException>(()=>BResultConsistencyReceipt.Read(p.ToString(),q));}
 [Test] public void RecoveryRejectsChangedImmutableReport(){var q=new BResultReportRequest(Original(),"restore");var changed=q.Body();changed["requestId"]="another";var m=new Mock{Reply=r=>Task.FromResult(Ok(new JObject{["receipt"]=Receipt(q),["report"]=changed}))};Assert.ThrowsAsync<ArgumentException>(async()=>await new BResultReportHttpClient(m).RecoverAsync(q,"B_RESULT:opaque/ref",Token()));}
 [Test] public async Task CancellationAfterServerResponsePreventsLocalPublication(){var q=new BResultReportRequest(Original(),"cancel");var gate=new TaskCompletionSource<GameApiAuthenticatedHttpResult>();var m=new Mock{Reply=r=>gate.Task};using(var ct=new CancellationTokenSource()){var call=new BResultReportHttpClient(m).SubmitAsync(q,Token(),ct.Token);ct.Cancel();gate.SetResult(Ok(Receipt(q)));try{await call;Assert.Fail();}catch(OperationCanceledException){}Assert.AreEqual(1,m.Calls);}}
 sealed class QueuedContext:SynchronizationContext {public readonly System.Collections.Generic.Queue<Action> Work=new System.Collections.Generic.Queue<Action>();public override void Post(SendOrPostCallback action,object state){Work.Enqueue(()=>action(state));}public void One(){Assert.Greater(Work.Count,0);Work.Dequeue()();}}
 [TestCase(1,false)][TestCase(4,false)][TestCase(4,true)] public async Task QueuedOuterContinuationCannotReturnReceiptAfterSourceChangeOrUnbind(int steps,bool changeSource){
  var shortMethod=typeof(BRuntimeObservationDeliveryTests).GetMethod("ShortSession",BindingFlags.Static|BindingFlags.NonPublic);using(var shortOwner=await (Task<BRouteSessionController>)shortMethod.Invoke(null,null)){
   var o=Original();var current=o;var replacement=shortOwner.CaptureOriginalRuntimeObservation();var q=new BResultReportRequest(o,"queued-race");var gate=new TaskCompletionSource<GameApiAuthenticatedHttpResult>();var mock=new Mock{Reply=r=>gate.Task};var c=new BRouteSessionController("a","LOCAL_B12_RUN");var flags=BindingFlags.Instance|BindingFlags.NonPublic;var field=typeof(BRouteSessionController).GetField("reportDelivery",flags);((IDisposable)field.GetValue(c)).Dispose();field.SetValue(c,Activator.CreateInstance(field.FieldType,flags,null,new object[]{new Func<BRouteRuntimeObservation>(()=>current)},null));var queued=new QueuedContext();var previous=SynchronizationContext.Current;Task<BResultReportDeliveryResult> task;
   try{SynchronizationContext.SetSynchronizationContext(queued);task=c.SubmitOriginalResultReportAsync(o,q,new BResultReportHttpClient(mock),Token());}finally{SynchronizationContext.SetSynchronizationContext(previous);}
   try{gate.SetResult(Ok(Receipt(q)));for(int i=0;i<steps;i++)queued.One();Assert.IsFalse(task.IsCompleted,"Receipt must still be awaiting its outer publication");if(changeSource){current=replacement;field.FieldType.GetMethod("InvalidateChangedSources",flags).Invoke(field.GetValue(c),null);}else c.Unbind();while(queued.Work.Count>0)queued.One();try{var result=await task;Assert.AreEqual(BLocalObservationDeliveryStatus.Superseded,result.Status);Assert.IsNull(result.Receipt);}catch(OperationCanceledException){}}finally{c.Dispose();}
  }
 }
 [TestCase(false)][TestCase(true)] public async Task ControllerUnbindOrDisposalCancelsReportingAndRejectsLateReceipt(bool dispose){var o=Original();var q=new BResultReportRequest(o,"lifetime");var gate=new TaskCompletionSource<GameApiAuthenticatedHttpResult>();var m=new Mock{Reply=r=>gate.Task};var type=typeof(BRouteSessionController);var c=new BRouteSessionController("a","LOCAL_B12_RUN");var flags=BindingFlags.Instance|BindingFlags.NonPublic;var field=type.GetField("reportDelivery",flags);var deliveryType=field.FieldType;var owner=Activator.CreateInstance(deliveryType,flags,null,new object[]{new Func<BRouteRuntimeObservation>(()=>o)},null);((IDisposable)field.GetValue(c)).Dispose();field.SetValue(c,owner);try{var task=c.SubmitOriginalResultReportAsync(o,q,new BResultReportHttpClient(m),Token());if(dispose)c.Dispose();else c.Unbind();gate.SetResult(Ok(Receipt(q)));try{await task;Assert.Fail("late receipt must not publish");}catch(OperationCanceledException){}}finally{c.Dispose();}}
}}
